function getBox(el) {
  const r = el.getBoundingClientRect();
  const hit = el.getAttribute('data-ai4a11y-bt-hit');
  let top = r.top, bottom = r.bottom, left = r.left, right = r.right;
  if (hit) {
    const [t, rt, b, l] = hit.split(' ').map(Number);
    top -= (t || 0);
    bottom += (b || 0);
    left -= (l || 0);
    right += (rt || 0);
  }
  return { top, bottom, left, right, el };
}

const interactive = [...document.querySelectorAll('button, a[href], input, [role="button"]')].filter((el) => {
  if (el.disabled || el.type === 'hidden') return false;
  const r = el.getBoundingClientRect();
  return r.width > 0 && r.height > 0;
});

const boxes = interactive.map(getBox);
for (let i = 0; i < boxes.length; i++) {
  for (let j = i + 1; j < boxes.length; j++) {
    const a = boxes[i];
    const b = boxes[j];
    if (a.el.contains(b.el) || b.el.contains(a.el)) continue;
    const overlapX = a.left < b.right - 0.5 && a.right > b.left + 0.5;
    const overlapY = a.top < b.bottom - 0.5 && a.bottom > b.top + 0.5;
    if (overlapX && overlapY) return false;
  }
}
return true;
